import { readFile, realpath } from 'fs/promises'
import { homedir } from 'os'
import path from 'path'

// The live map behind the Vitals tab mock-up (marvin#873). The map is brain-map/index.html (generated by
// brain-map/generate.py, the same page the wallpaper shows); in a browser it reads two live files next to it on its own
// 3 s tick (activity.jsonl for pulses, work.json for workers). This scheme serves exactly those: the page, its vendor
// scripts, and the two live files, from the one map folder. Any other path, any symlink out of the folder, and any
// other host is a 404. The page gets its own CSP: its own scripts, reads of this scheme only, no network.
export const MAP_SCHEME = 'marvin-map'
export const MAP_DIR = path.join(homedir(), '.agents', 'brain-map')
export const MAP_URL = `${MAP_SCHEME}://map/index.html`
export const MAP_CSP = `default-src 'none'; script-src ${MAP_SCHEME}: 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src ${MAP_SCHEME}:`

const FIXED = { '': 'index.html', 'index.html': 'index.html', 'work.json': 'work.json', 'activity.jsonl': 'activity.jsonl' }
const VENDOR = /^vendor\/[a-z0-9][a-z0-9.-]*\.js$/
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.json': 'application/json', '.jsonl': 'application/x-ndjson' }

export function mapFileFor(url, dir = MAP_DIR) {
  let u
  try { u = new URL(String(url)) } catch { return null }
  if (u.protocol !== `${MAP_SCHEME}:` || u.hostname !== 'map') return null
  let name
  try { name = decodeURIComponent(u.pathname.replace(/^\/+/, '')) } catch { return null }
  const rel = FIXED[name] ?? (VENDOR.test(name) && !name.includes('..') ? name : null)
  if (!rel) return null
  return { file: path.join(dir, rel), type: TYPES[path.extname(rel)] || 'application/octet-stream' }
}

const notFound = () => new Response('not found', { status: 404, headers: { 'content-type': 'text/plain' } })

export function createMapHandler({ dir = MAP_DIR } = {}) {
  return async (request) => {
    const hit = mapFileFor(request?.url, dir)
    if (!hit) return notFound()
    try {
      const [real, root] = await Promise.all([realpath(hit.file), realpath(dir)])
      if (!real.startsWith(root + path.sep)) return notFound()
      const body = await readFile(real)
      return new Response(body, { status: 200, headers: { 'content-type': hit.type, 'content-security-policy': MAP_CSP, 'cache-control': 'no-store' } })
    } catch {
      return notFound()
    }
  }
}
